# -*- coding: utf-8 -*-
import glob, json, sys, os, re
sys.path.insert(0, 'scripts')
from build_kanji_data import N5_MISSING

def get_pack_kanjis(lvl):
    packs = sorted(glob.glob(f'content/packs/{lvl}/*.json'))
    chars = {}
    for p in packs:
        d = json.load(open(p, encoding='utf-8'))
        for k in d.get('kanjis', []):
            ch = k.get('char') or k.get('kanji')
            if ch and ch not in chars:
                chars[ch] = k
    return chars

n5_pack = get_pack_kanjis('n5')
n4_pack = get_pack_kanjis('n4')
n3_pack = get_pack_kanjis('n3')
n2_pack = get_pack_kanjis('n2')

